package io.tenvyr.control.runtime;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.Db;
import io.tenvyr.platform.Json;
import io.tenvyr.control.engine.ExecutionService;
import java.time.Instant;
import java.util.*;

public final class HandoffService {
    private final Db db;private final ExecutionService executions;private final RuntimeCoordinationService coordination;private final WorkspaceExecutionService workspaces;
    public HandoffService(Db db,ExecutionService executions,RuntimeCoordinationService coordination,WorkspaceExecutionService workspaces){this.db=db;this.executions=executions;this.coordination=coordination;this.workspaces=workspaces;}
    public ObjectNode buildHandoffBundle(String source){return buildHandoffBundle(db,source);}
    public ObjectNode buildHandoffBundle(Db tx,String source){ObjectNode execution=tx.one("SELECT * FROM executions WHERE id=?",source);if(execution==null)throw fail("SOURCE_NOT_FOUND","Source execution missing");ObjectNode run=tx.one("SELECT * FROM coordination_runs WHERE \"executionId\"=?",source);if(run==null||!Coordination.TERMINAL.contains(Json.text(run,"phase")))throw fail("SOURCE_NOT_TERMINAL","Handoff requires a terminal coordinated run");ObjectNode iteration=tx.one("SELECT * FROM coordination_iterations WHERE \"coordinationRunId\"=? ORDER BY \"iterationNumber\" DESC LIMIT 1",run.get("id"));ArrayNode workers=Json.array(),artifacts=Json.array(),provenance=Json.array();if(iteration!=null)for(JsonNode entry:iteration.path("workerManifest")){if(workers.size()>=64)break;ObjectNode attempt=tx.one("SELECT status FROM step_attempts WHERE \"logicalStepId\"=? ORDER BY \"attemptNumber\" DESC LIMIT 1",entry.get("logicalStepId"));workers.add(Json.object("taskId",entry.get("taskId"),"status",attempt==null?"UNKNOWN":Json.text(attempt,"status"),"summary",null));}for(ObjectNode artifact:tx.query("SELECT a.id FROM artifacts a JOIN result_inbox r ON r.id=a.\"resultInboxId\" JOIN step_attempts s ON s.id=r.\"stepAttemptId\" WHERE s.\"executionId\"=? ORDER BY a.\"createdAt\" DESC LIMIT 64",source))artifacts.add(Json.object("artifactId",artifact.get("id"),"name",null));Set<String> dedup=new HashSet<>();for(ObjectNode attempt:tx.query("SELECT efficiency FROM step_attempts WHERE \"executionId\"=? ORDER BY \"createdAt\" ASC LIMIT 200",source)){JsonNode harness=attempt.path("efficiency").path("harness");if(!harness.hasNonNull("agent"))continue;String key=Json.text(harness,"agent")+"|"+Json.text(harness,"connectionId","")+"|"+Json.text(harness,"requestedModelId","");if(dedup.add(key)&&provenance.size()<64)provenance.add(Json.object("agent",harness.get("agent"),"connectionId",harness.get("connectionId"),"requestedModelId",harness.get("requestedModelId")));}JsonNode ws=run.get("workspace");ObjectNode lease=tx.one("SELECT * FROM workspace_executions WHERE \"ownerRunId\"=?",run.get("id")),plan=execution.hasNonNull("activePlanRevisionId")?tx.one("SELECT id,\"planHash\" FROM execution_plan_revisions WHERE id=?",execution.get("activePlanRevisionId")):null;JsonNode decision=iteration==null?null:iteration.get("decision");String next=Json.text(run,"waitReason",decision==null?Json.text(execution,"terminationReason",null):Json.text(decision,"reason",null));ObjectNode bundle=Json.object("schemaVersion",1,"sourceExecutionId",source,"sourceRunId",run.get("id"),"goal",truncate(Json.text(execution.path("input"),"goal",""),4096),"workspace",ws==null||ws.isNull()?null:Json.object("workspaceId",ws.get("workspaceId"),"path",ws.get("path"),"branch",ws.get("branch"),"headSha",ws.get("headSha")),"executionWorkspace",lease==null||!lease.hasNonNull("executionPath")?null:Json.object("workspaceExecutionId",lease.get("id"),"mode",lease.get("mode"),"path",lease.get("executionPath"),"baseHeadSha",lease.get("baseHeadSha"),"state",lease.get("state")),"planRevision",plan,"iterationNumber",run.get("currentIterationNumber"),"verifierDecision",decision==null||decision.isNull()?null:Json.object("action",truncate(Json.text(decision,"action",""),64),"reason",truncate(Json.text(decision,"reason",""),512)),"workerOutcomes",workers,"artifactRefs",artifacts,"acceptanceEvidence",run.get("acceptanceEvidence"),"nextWork",truncate(next,512),"sourceRuntimeProvenance",provenance,"createdAt",run.get("updatedAt"));return parseBundle(bundle);}
    public ObjectNode continueRun(Db tx,String source,JsonNode rawConfig,JsonNode rawBundle)throws Exception{ObjectNode bundle=parseBundle(rawBundle),config=Coordination.parseConfig(rawConfig);String hash=Json.hash(bundle);ObjectNode sourceRun=tx.one("SELECT * FROM coordination_runs WHERE \"executionId\"=? FOR UPDATE",source);if(sourceRun==null||!Coordination.TERMINAL.contains(Json.text(sourceRun,"phase"))||!Json.text(bundle,"sourceExecutionId").equals(source)||!Objects.equals(bundle.get("sourceRunId"),sourceRun.get("id")))throw fail("SOURCE_NOT_TERMINAL","Source must be terminal and match bundle");ObjectNode existing=tx.one("SELECT * FROM handoffs WHERE \"sourceExecutionId\"=? AND \"bundleHash\"=?",source,hash);if(existing!=null&&existing.hasNonNull("destinationExecutionId")){ObjectNode run=tx.one("SELECT id FROM coordination_runs WHERE \"executionId\"=?",existing.get("destinationExecutionId"));if(run!=null)return Json.object("executionId",existing.get("destinationExecutionId"),"runId",run.get("id"),"handoffId",existing.get("id"),"bundleHash",hash);}ObjectNode pipeline=tx.insert("pipelines",Json.object("name","continue:"+source.substring(0,Math.min(8,source.length())),"version","1.0","steps",Json.array()));ObjectNode execution=executions.materializeExecutionWithManager(tx.connection(),pipeline,Json.object("goal",bundle.get("goal"),"handoff",bundle),null);ObjectNode run=coordination.startRun(tx,Json.text(execution,"id"),config,Instant.now().plusMillis(Json.longValue(config,"loopDeadlineMs",0)),sourceRun.get("workspace"),sourceRun.get("acceptanceEvidence"));ObjectNode lease=tx.one("SELECT * FROM workspace_executions WHERE \"ownerRunId\"=?",sourceRun.get("id"));if(lease!=null&&Json.text(lease,"mode").equals("git-worktree"))workspaces.transferExecutionWorkspace(tx,Json.text(lease,"id"),Json.text(sourceRun,"id"),Json.text(run,"id"));else if(lease!=null)workspaces.allocateSharedExecutionWorkspace(tx,sourceRun.path("workspace"),Json.text(run,"id"));ObjectNode handoff=tx.insert("handoffs",Json.object("sourceExecutionId",source,"sourceRunId",sourceRun.get("id"),"bundleHash",hash,"bundle",bundle,"destinationExecutionId",execution.get("id"),"requester","operator"));coordination.createNextIteration(tx,Json.text(run,"id"));return Json.object("executionId",execution.get("id"),"runId",run.get("id"),"handoffId",handoff.get("id"),"bundleHash",hash);}
    public static ObjectNode parseBundle(JsonNode raw){ObjectNode n=RuntimeConnectionService.object(raw,"handoff",Set.of("schemaVersion","sourceExecutionId","sourceRunId","goal","workspace","executionWorkspace","planRevision","iterationNumber","verifierDecision","workerOutcomes","artifactRefs","acceptanceEvidence","nextWork","sourceRuntimeProvenance","createdAt"));Coordination.schema(n,"BUNDLE_INVALID");bounded(n,"sourceExecutionId",255,false);bounded(n,"sourceRunId",255,true);bounded(n,"goal",4096,false);bounded(n,"nextWork",512,true);bounded(n,"createdAt",64,false);if(n.hasNonNull("iterationNumber")&&(!n.get("iterationNumber").isIntegralNumber()||n.get("iterationNumber").asLong()<0))throw fail("BUNDLE_INVALID","Invalid iteration number");nested(n,"workspace",Map.of("workspaceId",255,"path",4096,"branch",255,"headSha",40),Set.of("branch","headSha"));nested(n,"executionWorkspace",Map.of("workspaceExecutionId",255,"mode",32,"path",4096,"baseHeadSha",40,"state",32),Set.of("baseHeadSha"));nested(n,"planRevision",Map.of("id",255,"planHash",64),Set.of());nested(n,"verifierDecision",Map.of("action",64,"reason",512),Set.of());entries(n,"workerOutcomes",Map.of("taskId",255,"status",32,"summary",2048),Set.of("summary"));entries(n,"artifactRefs",Map.of("artifactId",255,"name",255),Set.of("name"));entries(n,"sourceRuntimeProvenance",Map.of("agent",255,"connectionId",255,"requestedModelId",256),Set.of("connectionId","requestedModelId"));if(Json.bytes(n)>16384)throw fail("BUNDLE_TOO_LARGE","Handoff bundle exceeds 16384 bytes");return n;}
    private static void nested(JsonNode n,String field,Map<String,Integer> bounds,Set<String> nullable){if(n.hasNonNull(field)){JsonNode v=RuntimeConnectionService.object(n.get(field),field,bounds.keySet());bounds.forEach((key,max)->bounded(v,key,max,nullable.contains(key)));}}
    private static void entries(ObjectNode n,String field,Map<String,Integer> bounds,Set<String> nullable){if(!n.hasNonNull(field)){n.set(field,Json.array());return;}JsonNode list=n.get(field);if(!list.isArray()||list.size()>64)throw fail("BUNDLE_INVALID","Invalid "+field);for(JsonNode entry:list){RuntimeConnectionService.object(entry,field,bounds.keySet());bounds.forEach((key,max)->bounded(entry,key,max,nullable.contains(key)));}}
    private static void bounded(JsonNode n,String key,int max,boolean nullable){JsonNode v=n.get(key);if(nullable&&(v==null||v.isNull()))return;if(v==null||!v.isTextual()||v.asText().length()>max)throw fail("BUNDLE_INVALID","Invalid "+key);}
    static String truncate(String value,int max){return value==null?null:value.substring(0,Math.min(max,value.length()));}
    static RuntimeFailure fail(String code,String message){return new RuntimeFailure(code,message);}
}
